schemas.schema-02-actors.prisma:
/// Registered user accounts with email and password credentials, including
/// profile display name. This table handles authentication information and
/// user identity for the multi-user todo application. Supports soft deletion
/// via deleted_at field, allowing account deletion. Acts as the root actor
/// entity for user-related operations and relationships.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model multi_user_todo_users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for user authentication and communication.
  email String

  /// Hashed password for secure user authentication.
  password_hash String

  /// Display name for the user's profile.
  display_name String

  /// Timestamp when the user account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the user account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Nullable timestamp indicating when the account was soft deleted (null if
  /// active).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions multi_user_todo_user_sessions[]
  userPasswordResets multi_user_todo_user_password_resets[]
  emailVerifications multi_user_todo_user_email_verifications[]
  todos multi_user_todo_todos[]

  @@unique([email])
  @@index([created_at])
}

