  /// Belonged user's {@link multi_user_todo_users.id}.
  multi_user_todo_user_id String @db.Uuid

  /// IP address of the client initiating the session.
  ip String

  /// URL of the client at the time of session start.
  href String

  /// Referrer URL of the client, null if not available.
  referrer String?

  /// Session creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Session last update timestamp.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null if not deleted.
  deleted_at DateTime? @db.Timestamptz

  /// Timestamp when the session expires.
  expired_at DateTime @db.Timestamptz

  //----
