    body: joinBody,
  });
  userConnection.headers = { Authorization: authorized.token.access };
  // 2. Create a todo item
  const todoBeforeUpdate =
    await generate_random_multi_user_todo_user_todos_create(userConnection, {
      body: {
        title: RandomGenerator.name(),
